def _synchronize_execution_contracts():
    """Keep callable contracts byte-for-byte aligned with the canonical diagnostic registry."""
    try:
        from tis.contracts import load_diagnostic_registry
        canonical_rows = load_diagnostic_registry()
    except Exception:
        # Keep the conservative in-module contracts if packaged registry loading
        # is unavailable; never prevent numerical callables from importing.
        return
    canonical = {row["diagnostic"]: row["execution_contract"] for row in canonical_rows}
    for entry in ANALYSES:
        contract = canonical.get(entry["name"])
        if contract is not None:
            entry["execution_contract"] = deepcopy(contract)


_synchronize_execution_contracts()

def _sync_analysis_contracts_from_canonical_registry() -> None:
    """Use DIAGNOSTIC_REGISTRY.json as the single source of execution contracts.

    ANALYSES retains the stable IDs and Python entry-point mapping, while all
    input/output, uncertainty, provenance and branch-specific contracts are
    loaded from the canonical registry. This prevents dashboard/API metadata
    from drifting away from the public diagnostic catalogue.
    """
    import json
    from pathlib import Path

    root_registry = Path(__file__).resolve().parents[1] / "DIAGNOSTIC_REGISTRY.json"
    packaged_registry = Path(__file__).resolve().parents[1] / "tis" / "data" / "DIAGNOSTIC_REGISTRY.json"
    registry_path = root_registry if root_registry.is_file() else packaged_registry
    try:
        rows = json.loads(registry_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Cannot load canonical diagnostic execution contracts: {exc}") from exc
    by_name = {
        row.get("diagnostic"): row.get("execution_contract")
        for row in rows
        if isinstance(row, dict) and isinstance(row.get("execution_contract"), dict)
    }
    analysis_one_names = {
        "Thomson scattering",
        "Collective Thomson / coherent scattering (CTS)",
        "Thomson spatial profile reconstruction",
        "Thomson spectral distribution",
        "General relativistic 3-D optical Thomson EVDF reconstruction",
    }
    missing = sorted(name for name in analysis_one_names if name not in by_name)
    if missing:
        raise RuntimeError(f"Canonical diagnostic registry is missing Analysis 1 execution contracts for: {missing}")
    for entry in ANALYSES:
        if entry["name"] in analysis_one_names:
            contract = deepcopy(by_name[entry["name"]])
            primary = f"tokamak_analysis.{entry['module']}.{entry['function']}"
            if not contract.get("function_links") or contract["function_links"][0] != primary:
                raise RuntimeError(
                    f"Canonical Analysis 1 contract for {entry['name']} does not resolve to its registered entry point."
                )
            entry["execution_contract"] = contract


_sync_analysis_contracts_from_canonical_registry()



def get_analysis(analysis_id: int) -> dict:
    """Return a copy of a registered analysis entry by ordered list ID."""
    if isinstance(analysis_id, bool) or not isinstance(analysis_id, int):
        raise ValueError("analysis_id must be an integer.")
    for entry in ANALYSES:
        if entry["id"] == analysis_id:
            return deepcopy(entry)
    raise KeyError(f"Unknown analysis ID: {analysis_id}")


def resolve_analysis(analysis_id: int):
    """Import and return the registered callable for an analysis ID."""
    from importlib import import_module
    entry = get_analysis(analysis_id)
    module = import_module(f".{entry['module']}", package=__package__)
    return getattr(module, entry["function"])


def _load_analysis_families() -> list[dict]:
    """Load the canonical 20 primary-analysis families and validate their subanalysis map."""
    import json
    from pathlib import Path

    root_registry = Path(__file__).resolve().parents[1] / "ANALYSIS_FAMILIES.json"
    packaged_registry = Path(__file__).resolve().parents[1] / "tis" / "data" / "ANALYSIS_FAMILIES.json"
    registry_path = root_registry if root_registry.is_file() else packaged_registry
    try:
        payload = json.loads(registry_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError(f"Cannot load primary-analysis registry: {exc}") from exc
    families = payload.get("families") if isinstance(payload, dict) else None
    if not isinstance(families, list) or len(families) != 20:
        raise RuntimeError("ANALYSIS_FAMILIES.json must declare exactly 20 primary analyses.")
    family_ids = [item.get("id") for item in families]
    if family_ids != list(range(1, 21)):
        raise RuntimeError("Primary-analysis family IDs must be unique and ordered from 1 to 20.")
    entry_ids = [entry_id for family in families for entry_id in family.get("entry_ids", [])]
    expected_entry_ids = [entry["id"] for entry in ANALYSES]
    if sorted(entry_ids) != expected_entry_ids or len(set(entry_ids)) != len(expected_entry_ids):
        raise RuntimeError("Primary-analysis families must map every registered underlying analysis ID exactly once (ID 7 is retired).")
    return families


ANALYSIS_FAMILIES = _load_analysis_families()


def get_analysis_family(family_id: int) -> dict:
    """Return a defensive copy of one primary-analysis family."""
    if isinstance(family_id, bool) or not isinstance(family_id, int):
        raise ValueError("family_id must be an integer.")
    for family in ANALYSIS_FAMILIES:
        if family["id"] == family_id:
            return deepcopy(family)
    raise KeyError(f"Unknown primary-analysis family ID: {family_id}")


def get_family_entry_points(family_id: int) -> list[dict]:
    """Return the existing callable analysis records belonging to a primary family."""
    family = get_analysis_family(family_id)
    return [get_analysis(entry_id) for entry_id in family["entry_ids"]]
